INSERT INTO `v1_42461f68abc336e7d6c58dec840969fec1bc77983a5766f50230de57d97eb6d7` VALUES (82, "と、不退転の決意を申し上げたら、\nミサト様、「は～い♪」と、\n二つ返事で分かってくださって。", 0, 10, 0, 1, 11, 1, 0, 82025, 1);
